function CanReach(location)
    local entry = LOCATION_RULES[location]
    if not entry then
        return AccessibilityLevel.None
    end
    if type(entry) == "string" then
        return CanReachRegion(entry)
    end
    return And(CanReachRegion(entry[1]), entry[2]())
end
